// Sürekli ve sıçramasız saat yöneticisi
let lastKnownSourceTime=0;
let baseClockOffset=0;
let currentClockSource='none'; // 'audio' or 'perf'
let dancePauseTimestamp=0; // Sekme gizlendiğinde duraklatılan sanal saat anı

// Dinamik piksel hizalama parametreleri (getBoundingClientRect)
let dynamicHitY=52.5;
let dynamicTravelSpeed=52.5 / 1.8;

function updateDynamicHitMetrics(){
 const rhythmEl=document.querySelector('.rhythm');
 const hitlineEl=document.querySelector('.hitline');
 if(!rhythmEl||!hitlineEl)return;

 const rRect=rhythmEl.getBoundingClientRect();
 const hRect=hitlineEl.getBoundingClientRect();
 if(rRect.height===0)return;

 // Hitline merkezinin .rhythm üst sınırına göre piksel mesafesi
 const hitCenterFromTop=(hRect.top + hRect.height/2) - rRect.top;
 // Nota yüksekliği 24px (yarı yüksekliği 12px)
 const noteHalfHeight=12;
 // translateY = hitCenterFromTop - noteHalfHeight olduğunda nota merkezi hitline merkeziyle tam çakışır
 dynamicHitY=hitCenterFromTop - noteHalfHeight;
 dynamicTravelSpeed=dynamicHitY / 1.8; // 1.8 saniyede yukarıdan hedef çizgisine varış
}

window.addEventListener('resize', updateDynamicHitMetrics);

function initAudioContext(){
 if(!audioCtx){
  const AudioContextClass=window.AudioContext||window.webkitAudioContext;
  if(AudioContextClass){
   try{
    audioCtx=new AudioContextClass();
   }catch(e){
    console.warn('AudioContext başlatılamadı, performance.now() tabanlı saate geçiliyor:', e);
   }
  }
 }
 if(audioCtx&&audioCtx.state==='suspended'&&danceState!==DANCE_STATES.PAUSED){
  audioCtx.resume().catch(e=>console.warn('AudioContext resume hatası:', e));
 }
}

function getGameTimeSec(){
 let isAudioRunning=audioCtx&&audioCtx.state==='running';
 let activeSource=isAudioRunning?'audio':'perf';
 let rawTime=isAudioRunning?audioCtx.currentTime:(performance.now()/1000);

 if(currentClockSource==='none'){
  currentClockSource=activeSource;
  lastKnownSourceTime=rawTime;
  baseClockOffset=0;
 }else if(currentClockSource!==activeSource){
  let oldVirtualTime=lastKnownSourceTime + baseClockOffset;
  baseClockOffset=oldVirtualTime - rawTime;
  currentClockSource=activeSource;
 }

 lastKnownSourceTime=rawTime;
 return rawTime + baseClockOffset;
}

// Sekme görünürlük koruması (document.visibilitychange)
document.addEventListener('visibilitychange', ()=>{
 if(document.hidden){
  resetInput();
  if(danceState===DANCE_STATES.PLAYING||danceState===DANCE_STATES.COUNTDOWN){
   pauseDanceTur();
  }
 }
});

function pauseDanceTur(){
 resetInput();
 if(danceState!==DANCE_STATES.PLAYING&&danceState!==DANCE_STATES.COUNTDOWN)return;
 dancePauseTimestamp=getGameTimeSec();
 if(countdownTimer){
  clearInterval(countdownTimer);
  countdownTimer=null;
 }
 danceState=DANCE_STATES.PAUSED;
 if(audioCtx&&audioCtx.state==='running'){
  audioCtx.suspend().catch(()=>{});
 }
 document.getElementById('dancepause').hidden=false;
}

function resumeDanceTur(){
 if(danceState!==DANCE_STATES.PAUSED)return;
 document.getElementById('dancepause').hidden=true;
 initAudioContext();
 if(audioCtx&&audioCtx.state==='suspended'){
  audioCtx.resume().catch(()=>{});
 }
 // Saat sıçramasını önle: duraklatmada geçen süreyi startSec ve countdown'a ekle
 let nowSec=getGameTimeSec();
 let pauseDuration=nowSec - dancePauseTimestamp;
 danceGame.startSec += pauseDuration;

 if(countdownSec > 0){
  danceState=DANCE_STATES.COUNTDOWN;
  countdownTimer=setInterval(()=>{
   countdownSec--;
   if(countdownSec > 0){
    document.getElementById('timer').textContent=countdownSec;
    status.textContent='Dans başlıyor: '+countdownSec+'...';
   }else{
    clearInterval(countdownTimer);
    countdownTimer=null;
    beginDancePlay();
   }
  }, 1000);
 }else{
  danceState=DANCE_STATES.PLAYING;
 }
}

function quitDanceFromPause(){
 document.getElementById('dancepause').hidden=true;
 finishDance(true);
}

document.getElementById('dance-resume').onclick=resumeDanceTur;
document.getElementById('dance-quit').onclick=quitDanceFromPause;

// Beatmap Yönetimi
const loadedBeatmaps={};
let currentBeatmapId='meydan_demo';
let currentDifficulty='easy';

function validateBeatmap(bm){
 if(!bm||typeof bm!=='object')throw new Error('Beatmap geçersiz veya boş!');
 if(!bm.id||typeof bm.id!=='string')throw new Error('Beatmap geçerli bir "id" içermeli!');
 if(!bm.title||typeof bm.title!=='string')throw new Error('Beatmap geçerli bir "title" içermeli!');
 if(typeof bm.bpm!=='number'||bm.bpm<=0)throw new Error('Beatmap geçerli bir pozitif "bpm" içermeli!');
 if(!bm.difficulties||typeof bm.difficulties!=='object'||Object.keys(bm.difficulties).length===0){
  throw new Error('Beatmap en az bir zorluk seviyesi ("difficulties") içermeli!');
 }
 const validKeys=['left','up','down','right'];
 for(let [diffName, diffObj] of Object.entries(bm.difficulties)){
  if(!diffObj||!Array.isArray(diffObj.notes)){
   throw new Error(`"${diffName}" zorluğu geçerli bir "notes" dizisi içermeli!`);
  }
  let prevTime=-1;
  for(let n of diffObj.notes){
   if(typeof n.timeMs!=='number'||n.timeMs<0){
    throw new Error(`"${diffName}" içinde geçersiz timeMs (${n.timeMs}) tespit edildi! Negatif olamaz.`);
   }
   if(!validKeys.includes(n.key)){
    throw new Error(`"${diffName}" içinde geçersiz nota tuşu: "${n.key}". Yalnızca left/up/down/right olmalıdır.`);
   }
   if(n.timeMs < prevTime){
    throw new Error(`"${diffName}" notaları kronolojik sıralı değil! (${n.timeMs} < ${prevTime})`);
   }
   prevTime=n.timeMs;
  }
 }
 return true;
}

async function loadBeatmap(id){
 if(loadedBeatmaps[id])return loadedBeatmaps[id];
 if(window.EMBEDDED_BEATMAPS&&window.EMBEDDED_BEATMAPS[id]){
  try{
   let bm=window.EMBEDDED_BEATMAPS[id];
   validateBeatmap(bm);
   loadedBeatmaps[id]=bm;
   return bm;
  }catch(err){
   console.error('Gömülü beatmap doğrulama hatası:', err);
   notify('Hatalı Beatmap: '+err.message);
   throw err;
  }
 }
 try{
  let res=await fetch('./beatmaps/'+id+'.json');
  if(!res.ok)throw new Error('Beatmap dosyası bulunamadı: '+id);
  let bm=await res.json();
  validateBeatmap(bm);
  loadedBeatmaps[id]=bm;
  return bm;
 }catch(err){
  console.error('Beatmap yüklenemedi:', err);
  notify('Beatmap yüklenemedi: '+err.message);
  throw err;
 }
}

