 const open=[start],seen=new Set([key(...start)]),parent=new Map();let last=null;
 for(let i=0;i<open.length&&i<5000;i++){let c=open[i];if(c[0]===end[0]&&c[1]===end[1]){last=c;break}for(let d of [[1,0],[-1,0],[0,1],[0,-1]]){let n=[c[0]+d[0],c[1]+d[1]],k=key(...n);if(!seen.has(k)&&!blocked(n[0]*step,n[1]*step)){seen.add(k);parent.set(k,c);open.push(n)}}}
