function interact(){
 if(!player)return;
 if(player.position.z>8){
  notify('Sahil yürüyüşüne hoş geldin.');
 }else if(player.position.x< -2&&player.position.z<1.5){
  if(!tourDone){
   tourDone=true;
   points+=50;
   document.getElementById('quest').textContent='✓ Kafeyi keşfet · +50 puan';
   updateScore();
  }
  notify('Kafe keşfi tamamlandı. Dans pistine veya sahile geçebilirsin.');
 }else if(player.position.distanceTo(new THREE.Vector3(1.5,0.1,-1.5))<3){
  if(danceState===DANCE_STATES.IDLE)toggleDance();
  notify('Dans pistindesin. Ok dizisini tamamla.');
 }else{
  notify('Keşfet: kafe solda, dans pisti ileride, sahil arkanda.');
 }
}

function updateScore(){
 document.getElementById('score').textContent=points+' PUAN';
}

function judge(kind){
 let values={perfect:1000,great:650,good:350,miss:0};
 danceGame.stats[kind]++;
 if(kind==='miss'){
  danceGame.combo=0;
 }else{
  danceGame.combo++;
  danceGame.maxCombo=Math.max(danceGame.maxCombo,danceGame.combo);
  danceGame.roundScore+=values[kind]+danceGame.combo*15;
 }
 document.getElementById('combo').textContent='COMBO '+danceGame.combo;
 status.textContent=kind==='perfect'?'PERFECT!':kind==='great'?'GREAT!':kind==='good'?'GOOD':'MISS';
}

function input(k){
 if(paused||document.hidden||danceState!==DANCE_STATES.PLAYING||!sequence.includes(k))return;
 let dir=sequence.indexOf(k);
 let button=document.querySelectorAll('.key')[dir];
 if(button){
  button.classList.add('hit');
  setTimeout(()=>button.classList.remove('hit'),90);
 }

 // Puanlama zamanı: AudioContext saatine dayalı
 let elapsedSec=getGameTimeSec()-danceGame.startSec;

 // Gecikmiş notaları (delta > 0.350s) tek tek Miss say ve tüket
 while(danceGame.index<danceGame.notes.length){
  let n=danceGame.notes[danceGame.index];
  if(elapsedSec - n.timeSec > 0.350){
   if(!n.hit&&!n.missed){
    n.missed=true;
    n.el?.remove();
    judge('miss');
   }
   danceGame.index++;
  }else{
   break;
  }
 }

 let note=danceGame.notes[danceGame.index];
 if(!note)return;

 let timeDiffSec=note.timeSec - elapsedSec; // pozitif = erken, negatif = geç
 let absDiffSec=Math.abs(timeDiffSec);

 if(timeDiffSec > 0.350){
  // 350 ms'den daha erken: notayı tüketmez, yalnızca erken uyarısı
  danceGame.combo=0;
  document.getElementById('combo').textContent='COMBO 0';
  status.textContent='ERKEN!';
  return;
 }

 if(note.dir!==dir){
  // Yanlış yön: combo sıfırlanır, aktif notayı tüketmez
  danceGame.combo=0;
  document.getElementById('combo').textContent='COMBO 0';
  status.textContent='YANLIŞ TUŞ!';
  return;
 }

 // Doğru yön ve ±350 ms aralığında
 if(absDiffSec<=0.120)judge('perfect');
 else if(absDiffSec<=0.220)judge('great');
 else if(absDiffSec<=0.350)judge('good');

 note.hit=true;
 note.el?.remove();
 danceGame.index++;
}

